"""Stage H (30 Oct 2026): figure environments for the redrawn figures, writing pass over the carried-over
prose (Secs. 1-4, App. A, B, D-G), consistency fixes and the data-availability statement.
Runs inside apply_text_pipeline.sh after stageG_stats and before reorder_bib.
No result changes here; dispatch results for the low-resource day are written by stageH_dispatch.py."""
from texedit import Ed

E = Ed()


def para(prefix, new):
    """Replace the single source line (paragraph) that starts with `prefix`."""
    lines = E.s.split('\n'); idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    if len(idx) != 1: raise SystemExit(f'paragraph prefix found {len(idx)}x: {prefix[:70]!r}')
    lines[idx[0]] = new; E.s = '\n'.join(lines); E.log.append('para:' + prefix[:50])


def block(start, end, new):
    """Replace from `start` through `end` (inclusive)."""
    E.between(start, end, new)


